using System.Security.Cryptography;
using System.Text.Json;
namespace UnscRelay.Core;
internal sealed record WindowsHelloRegistrations(int Version,string Owner,string Subject,WindowsHelloChallenge[] Keys);
/// <summary>Retains only credential names authenticated by a successfully opened vault.</summary>
public sealed class WindowsHelloRegistration(string directory)
{
 const string FileName="account-hello.dpapi";
 static void Validate(WindowsHelloChallenge key){const string prefix="UNSC-Relay-Vault-";if(key.KeyName is null||!key.KeyName.StartsWith(prefix,StringComparison.Ordinal)||!Guid.TryParseExact(key.KeyName[prefix.Length..],"N",out _)||key.PublicKey is null||key.PublicKey.Length is <1 or >8192||key.Message is null||key.Message.Length>512)throw new InvalidDataException("Collegamento Windows Hello non valido.");try{var bytes=Convert.FromBase64String(key.PublicKey);if(bytes.Length<32)throw new InvalidDataException("Chiave pubblica Windows Hello non valida.");}catch(FormatException error){throw new InvalidDataException("Chiave pubblica Windows Hello non valida.",error);}}
 internal WindowsHelloChallenge[] Load(string owner,string subject){if(!File.Exists(LocalDataFiles.Child(directory,FileName)))return [];var sealedBytes=LocalDataFiles.Read(directory,FileName,256*1024);byte[]? bytes=null;try{bytes=UpdateTokenStore.Transform(sealedBytes,true);var value=JsonSerializer.Deserialize<WindowsHelloRegistrations>(bytes,VaultSyncCrypto.Json)??throw new InvalidDataException("Registro Windows Hello non valido.");if(value.Version!=1||value.Owner!=owner||value.Subject!=subject||value.Keys is null||value.Keys.Length>1000)throw new InvalidDataException("Registro Windows Hello di un altro account.");foreach(var key in value.Keys)Validate(key);return value.Keys;}finally{CryptographicOperations.ZeroMemory(sealedBytes);if(bytes!=null)CryptographicOperations.ZeroMemory(bytes);}}
 public void Remember(KeyVault authenticatedVault,AccountSyncState account){var challenge=authenticatedVault.AuthenticatedWindowsHello();if(challenge==null||account.Owner.Length==0)return;RememberAuthenticated(challenge,account.Owner,account.Subject);}
 internal void RememberAuthenticated(WindowsHelloChallenge challenge,string owner,string subject){if(owner is not{Length:64}||!owner.All(char.IsAsciiHexDigit)||!Guid.TryParseExact(subject,"D",out _))throw new InvalidDataException("Identità Windows Hello non valida.");Validate(challenge);var keys=Load(owner,subject).Append(challenge).DistinctBy(value=>(value.KeyName,value.PublicKey)).ToArray();if(keys.Length>1000)throw new InvalidDataException("Troppi collegamenti Windows Hello.");var bytes=JsonSerializer.SerializeToUtf8Bytes(new WindowsHelloRegistrations(1,owner,subject,keys),VaultSyncCrypto.Json);try{LocalDataFiles.Write(directory,FileName,UpdateTokenStore.Transform(bytes,false));}finally{CryptographicOperations.ZeroMemory(bytes);}}
}
